/* MINOR INDEX — the build.
 *
 * The plate code is CommonJS because node runs it; the atelier is a page
 * because a page is what a hand can hold. This makes the second out of the
 * first so there is one copy of the vocabulary and not two.
 *
 * Each module keeps its own scope — the files are wrapped, not stripped, and
 * given a `require` that resolves to the ones already built. That matters:
 * `_letters.js` has a `G` (the glyph table) and `_mark.js` has a `G` (the SVG
 * group), and in one shared scope one of them would quietly win.
 *
 * Nothing hand-written lives in `docs/`. The two pages are written in `src/`
 * and copied out with the ink table filled in from `_mark.js`, so the site is
 * a build product all the way down and can be deleted and made again.
 *
 *   node logo/mkbundle.js       → logo/docs/
 *   require("./mkbundle.js").build()   → { filename: contents }, written nowhere
 */
const fs = require("fs");
const path = require("path");
const { INK } = require("./_mark.js");

/* in dependency order */
const SRC = ["_mark.js", "_press.js", "_glyphs.js", "_letters.js", "_furniture.js",
             "_font.js", "_raster.js", "_studio.js"];
/* what the page gets on window.MINOR */
const EXPOSE = {
  "_mark.js": ["INK", "GROT", "MONO", "n", "rng", "pick", "segDist", "L", "axes", "brackets",
    "trim", "polar", "swipe", "under", "svg", "svgOpen", "SVG_CLOSE", "G"],
  "_glyphs.js": ["blob", "cell", "sunGeom", "sunSolid", "sunSDF", "sunWhirl", "screen",
    "cellGeom", "cellSDF", "phylloPts", "sPts", "sScatter", "nearest", "spiralPath", "spiralWalls",
    "sSpiral", "sDisc", "sRing", "sBox", "sUnion", "sSub", "sShift", "sTwist", "sGrow",
    "sSmooth", "sMorph", "noise2", "sWobble", "contour", "sBite", "sunBound", "cellBound"],
  "_raster.js": ["screenImage", "bbox"],
  "_studio.js": ["PARAMS", "FIELDS", "DEFAULTS", "SHEETS", "INKS", "buildPlate", "emitPlate",
    "rollState", "sheetOf", "visible", "stMetrics", "compactDots", "useImage", "theImage"],
};
/* and two namespaces, kept whole */
const NAMESPACES = { text: "_letters.js", font: "_font.js" };

const dir = __dirname;
const readSrc = (f) => fs.readFileSync(path.join(dir, f), "utf8");

/* the ink table, as CSS custom properties, so a page cannot invent a palette */
const inkCSS = "    " + Object.keys(INK).map((k) => `--${k}:${INK[k]};`).join(" ")
  + "   /* the ink table, from _mark.js */";

/** the modules as one file, each still in its own scope */
function bundle() {
  const wrapped = SRC.map((f) =>
    `/* ==== ${f} ${"=".repeat(Math.max(0, 60 - f.length))} */\n`
    + `__MI__[${JSON.stringify(f)}] = (function () {\n`
    + `var module = { exports: {} }, exports = module.exports;\n`
    + `var require = function (p) { return __MI__[p.replace("./", "")]; };\n`
    + readSrc(f)
    + `\nreturn module.exports;\n})();`);
  const picks = [];
  for (const f in EXPOSE) for (const k of EXPOSE[f]) picks.push(`  ${k}: __MI__[${JSON.stringify(f)}].${k},`);
  for (const ns in NAMESPACES) picks.push(`  ${ns}: __MI__[${JSON.stringify(NAMESPACES[ns])}],`);
  return `/* MINOR INDEX — generated by mkbundle.js. Do not edit: edit the modules.
   ${SRC.join(" + ")} → one file, each module still in its own scope. */
(function (global) {
"use strict";
var __MI__ = {};   /* the registry, named so no module can shadow it */
${wrapped.join("\n\n")}

global.MINOR = {
${picks.join("\n")}
};
})(typeof window !== "undefined" ? window : self);
`;
}

/* a page, with the ink table written into it */
const page = (name) => readSrc(path.join("src", name))
  .replace(/^ *\/\* @INK[^\n]*\n/m, inkCSS + "\n");

/* nothing may end a script tag from inside one */
const inTag = (js) => js.replace(/<\/(script)/gi, "<\\/$1");

/** everything docs/ is made of, as { filename: contents } */
function build() {
  const b = bundle();
  const worker = readSrc(path.join("src", "press.worker.js"));
  const index = page("index.html");
  const spec = page("specimen.html");
  const out = {
    "_bundle.js": b,
    /* the worker, for a site that is served: it fetches the vocabulary beside it */
    "_worker.js": '/* generated by mkbundle.js — edit src/press.worker.js */\n'
      + 'importScripts("_bundle.js");\n' + worker,
    "index.html": index,
    "specimen.html": spec,
  };
  /* one self-contained file for the Claude artifact, which wraps the page in a
     document of its own and so must not be given a second doctype. The press
     worker is carried inside it as text and started from a blob, because a
     single file has no sibling to fetch — which is also what makes the atelier
     work when it is opened straight off the disk. */
  out["atelier.html"] = index
    .replace('<script src="_bundle.js"></script>', `<script>\n${inTag(b)}\n</script>`)
    .replace('<script id="press-worker" type="text/plain"></script>',
      `<script id="press-worker" type="text/plain">\n${inTag(b + "\n" + worker)}\n</script>`)
    .replace(/^<!doctype html>\s*/i, "");
  return out;
}

module.exports = { build, bundle, EXPOSE, SRC };

if (require.main === module) {
  const web = path.join(dir, "docs");        /* GitHub Pages serves this folder */
  fs.mkdirSync(web, { recursive: true });
  fs.writeFileSync(path.join(web, ".nojekyll"), "");
  const out = build();
  for (const f in out) {
    fs.writeFileSync(path.join(web, f), out[f]);
    console.log(`docs/${f}`.padEnd(24) + `${(out[f].length / 1024).toFixed(0)}kb`);
  }
  console.log("→ docs/ is a build product: every file in it is written by this script");
}
